  ) as t(id, new_date, new_label, new_title, old_title) loop
    update events set
      event_date = coalesce(event_date, v.new_date),
      date_label = case when event_date is null then v.new_label else date_label end,
      end_date = case when event_date is null and v.new_label is null then v.new_date else end_date end,
      title = coalesce(v.new_title, title)
    where id = v.id and title = v.old_title and pool = 0 and (v.new_date is null or event_date is null);
    if not found then raise exception '想定と違う行があるので取り消しました: %', v.id; end if;
    v_done := v_done + 1;
  end loop;

  if v_done <> 256 then raise exception '件数が想定と違うので取り消しました（%件）', v_done; end if;
end $$;
